input.sparql:
SELECT ?zone ?ts WHERE {
  ?zone brick:hasSubclass* brick:PerimeterZone ;
        rdfs:label ?label .
  FILTER(?label = "Perimeter_mid_ZN_1")
  ?point ref:isPointOf ?zone .
  ?point ref:hasTimeseriesId ?ts .
  ?point rdf:type ?pt .
}

SELECT ?point ?ts WHERE {
  <http://buildgraph.org/BG_medium_office_2004_0000#Zone_F2_Z02> brick:hasPoint ?point .
  ?point a brick:Occupancy_Sensor .
  ?point ref:hasExternalReference ?ex .
  ?ex ref:hasTimeseriesId ?ts .
}
